from __future__ import annotations

import sqlite3
import zipfile
from pathlib import Path

import pytest

import famed.dna_replay as dna_replay
from famed import dependent_reports
from famed.dna_replay import replay_retained_dna_sources
from famed.findings_ledger import record_finding
from famed.setup import initialize_database

_DNA_SAMPLE = (
    "# This data file generated by 23andMe\n"
    "# Genome build: b37\n"
    "# Genotype build: v5\n"
    "# rsid\tchromosome\tposition\tgenotype\n"
    "rs1000001\t1\t100001\tAA\n"
    "rs1000002\t1\t100002\tAG\n"
)


def _target(tmp_path: Path) -> tuple[Path, Path, sqlite3.Connection]:
    vault = tmp_path / "vault"
    processed = tmp_path / "processed"
    (vault / "Persons").mkdir(parents=True)
    (vault / "Persons" / "dummy_person.md").write_text(
        "---\n"
        "person_id: dummy_person\n"
        "record_type: person\n"
        "display_name: Dummy Person\n"
        "birth_year: 1990\n"
        "sex: unknown\n"
        "relationships: []\n"
        "---\n\n"
        "# Dummy Person\n",
        encoding="utf-8",
    )
    db_path = tmp_path / "target.db"
    initialize_database(db_path)
    conn = sqlite3.connect(db_path)
    conn.execute(
        "INSERT INTO persons (id, display_name, birth_year, sex) VALUES (?, ?, ?, ?)",
        ("dummy_person", "Dummy Person", 1990, "unknown"),
    )
    conn.commit()
    return vault, processed, conn


def _write_zip_source(processed: Path) -> Path:
    genes = processed / "dummy_person" / "Genes"
    genes.mkdir(parents=True)
    source = genes / "2099-01-02-synthetic-genome-v5.txt.zip"
    with zipfile.ZipFile(source, "w") as archive:
        archive.writestr("synthetic-genome-v5.txt", _DNA_SAMPLE)
    return source


def test_replay_retained_dna_is_idempotent_and_preserves_source(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    vault, processed, conn = _target(tmp_path)
    source = _write_zip_source(processed)
    source_before = source.read_bytes()
    refresh_calls: list[tuple[str, Path | None]] = []

    def fake_refresh(
        _conn: sqlite3.Connection,
        _vault: Path,
        person_id: str,
        *,
        ref_db_path: Path | None = None,
        findings_ledger_path: Path | None = None,
    ) -> list[Path]:
        refresh_calls.append((person_id, findings_ledger_path))
        return []

    monkeypatch.setattr(dna_replay, "refresh_dna_dependent_reports", fake_refresh)
    try:
        first = replay_retained_dna_sources(
            root=tmp_path,
            vault_root=vault,
            processed_root=processed,
            conn=conn,
        )
        first_notes = {path.relative_to(vault): path.read_bytes() for path in vault.rglob("*.md")}
        second = replay_retained_dna_sources(
            root=tmp_path,
            vault_root=vault,
            processed_root=processed,
            conn=conn,
        )

        assert first == second
        assert first.source_files == 1
        assert first.import_rows == 1
        assert first.genotype_rows == 2
        assert conn.execute("SELECT COUNT(*) FROM dna_imports").fetchone() == (1,)
        assert conn.execute("SELECT COUNT(*) FROM genotypes").fetchone() == (2,)
        assert conn.execute("SELECT source_path, imported_at FROM dna_imports").fetchone() == (
            "data/processed/dummy_person/Genes/2099-01-02-synthetic-genome-v5.txt.zip",
            "2099-01-02",
        )
        assert {
            path.relative_to(vault): path.read_bytes() for path in vault.rglob("*.md")
        } == first_notes
        assert refresh_calls == [
            ("dummy_person", None),
            ("dummy_person", None),
        ]
        assert source.read_bytes() == source_before
        assert (
            vault
            / "Records"
            / "dummy_person"
            / "Genes"
            / "2099-01-02-synthetic-genome-v5-txt-dna.md"
        ).is_file()
    finally:
        conn.close()


def test_replay_rolls_back_database_and_vault_when_report_refresh_fails(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    vault, processed, conn = _target(tmp_path)
    source = _write_zip_source(processed)
    marker = vault / "Records" / "dummy_person" / "History" / "existing.md"
    marker.parent.mkdir(parents=True)
    marker.write_text("existing", encoding="utf-8")
    source_before = source.read_bytes()

    def fail_refresh(*_args: object, **_kwargs: object) -> list[Path]:
        raise RuntimeError("synthetic report failure")

    monkeypatch.setattr(dna_replay, "refresh_dna_dependent_reports", fail_refresh)
    try:
        with pytest.raises(RuntimeError, match="synthetic report failure"):
            replay_retained_dna_sources(
                root=tmp_path,
                vault_root=vault,
                processed_root=processed,
                conn=conn,
            )

        assert conn.execute("SELECT COUNT(*) FROM dna_imports").fetchone() == (0,)
        assert conn.execute("SELECT COUNT(*) FROM genotypes").fetchone() == (0,)
        assert marker.read_text(encoding="utf-8") == "existing"
        assert list((vault / "Records" / "dummy_person" / "Genes").glob("*-dna.md")) == []
        assert source.read_bytes() == source_before
    finally:
        conn.close()


def test_replay_rejects_malformed_dna_before_mutating_target(tmp_path: Path) -> None:
    vault, processed, conn = _target(tmp_path)
    genes = processed / "dummy_person" / "Genes"
    genes.mkdir(parents=True)
    (genes / "2099-01-02-malformed.txt").write_text("not DNA", encoding="utf-8")
    try:
        with pytest.raises(ValueError, match="unsupported DNA format"):
            replay_retained_dna_sources(
                root=tmp_path,
                vault_root=vault,
                processed_root=processed,
                conn=conn,
            )

        assert conn.execute("SELECT COUNT(*) FROM dna_imports").fetchone() == (0,)
        assert conn.execute("SELECT COUNT(*) FROM genotypes").fetchone() == (0,)
        assert list((vault / "Records").rglob("*")) == []
    finally:
        conn.close()


def test_replay_rejects_impossible_retained_date_before_mutating_target(
    tmp_path: Path,
) -> None:
    vault, processed, conn = _target(tmp_path)
    genes = processed / "dummy_person" / "Genes"
    genes.mkdir(parents=True)
    (genes / "2099-99-99-synthetic-genome.txt").write_text(_DNA_SAMPLE, encoding="utf-8")
    try:
        with pytest.raises(ValueError, match="invalid import-date prefix"):
            replay_retained_dna_sources(
                root=tmp_path,
                vault_root=vault,
                processed_root=processed,
                conn=conn,
            )

        assert conn.execute("SELECT COUNT(*) FROM dna_imports").fetchone() == (0,)
        assert conn.execute("SELECT COUNT(*) FROM genotypes").fetchone() == (0,)
        assert not (vault / "Records").exists()
    finally:
        conn.close()


def test_replay_rolls_back_first_source_when_later_parse_fails(tmp_path: Path) -> None:
    vault, processed, conn = _target(tmp_path)
    genes = processed / "dummy_person" / "Genes"
    genes.mkdir(parents=True)
    first = genes / "2099-01-02-a-synthetic-genome.txt"
    first.write_text(_DNA_SAMPLE, encoding="utf-8")
    second = genes / "2099-01-03-b-malformed-genome.txt"
    second.write_text("# This data file generated by 23andMe\n", encoding="utf-8")
    source_bytes = {path: path.read_bytes() for path in (first, second)}
    try:
        with pytest.raises(ValueError, match="no column header"):
            replay_retained_dna_sources(
                root=tmp_path,
                vault_root=vault,
                processed_root=processed,
                conn=conn,
            )

        assert conn.execute("SELECT COUNT(*) FROM dna_imports").fetchone() == (0,)
        assert conn.execute("SELECT COUNT(*) FROM genotypes").fetchone() == (0,)
        assert list((vault / "Records").rglob("*")) == []
        assert {path: path.read_bytes() for path in (first, second)} == source_bytes
    finally:
        conn.close()


def test_replay_real_composites_ignore_default_working_ledger(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    vault, processed, conn = _target(tmp_path)
    _write_zip_source(processed)
    working_root = tmp_path / "working"
    working_root.mkdir()
    monkeypatch.chdir(working_root)
    ledger = working_root / "ledger" / "findings.jsonl"
    marker = "WORKING-LEDGER-ONLY-MARKER"
    record_finding(
        ledger,
        finding_id="working-only",
        person_id="dummy_person",
        domain="PGx readiness",
        statement=marker,
        evidence_tier="E3",
        confidence=0.6,
        evidence_check="lower_confidence_unverified",
        source_paths=["Records/dummy_person/Reports/pgx-coverage.md"],
    )
    ledger_before = ledger.read_bytes()

    def write_first_tier(
        _conn: sqlite3.Connection,
        passed_vault: Path,
        person_id: str,
        *_args: object,
        **_kwargs: object,
    ) -> tuple[Path, list[object]]:
        reports = passed_vault / "Records" / person_id / "Reports"
        reports.mkdir(parents=True, exist_ok=True)
        path = reports / "synthetic-first-tier.md"
        path.write_text("# Synthetic first tier\n", encoding="utf-8")
        return path, []

    def write_health(
        passed_vault: Path,
        person_id: str,
        **_kwargs: object,
    ) -> tuple[Path, int]:
        path = passed_vault / "Records" / person_id / "Reports" / "health-advisory.md"
        path.write_text("# Synthetic health advisory\n", encoding="utf-8")
        return path, 0

    monkeypatch.setattr(
        dependent_reports,
        "write_genetics_report",
        lambda conn, vault, person_id, *_a, **_k: write_first_tier(conn, vault, person_id)[0],
    )
    monkeypatch.setattr(dependent_reports, "write_health_advisory", write_health)
    try:
        replay_retained_dna_sources(
            root=tmp_path,
            vault_root=vault,
            processed_root=processed,
            conn=conn,
        )

        for filename in ("medication-safety-alerts.md",):
            content = (vault / "Records" / "dummy_person" / "Reports" / filename).read_text(
                encoding="utf-8"
            )
            assert marker not in content
        assert ledger.read_bytes() == ledger_before
    finally:
        conn.close()
